UI={
'ru':dict(nav=['Программа','Послушать','Инструкция'],title=['Твоя музыка.','Твоя плотность.'],lead='Знакомый аналоговый характер. Сравни с оригиналом и сохрани свой MP3.',shared='Общий установщик с YouTube Downloader',heading='Послушай разницу',intro='Три музыкальных фрагмента. Выбери трек, нажми Play на проигрывателе и поверни ручку PeakMP3.',note='Плотности 0–10 заранее обработаны движком PeakMP3 0.16.0. A — исходный фрагмент, B — выбранная обработка. Демо не обрабатывает твои файлы в браузере.',hint='Крути ручку, нажимай пресеты, A/B и кнопки проигрывателя. Перемотка — по звуковой волне, громкость — фейдером справа.',credit='Музыка и лицензии',changes='Фрагменты по 24 секунды: обрезка, обработка PeakMP3 и кодирование MP3. Лицензия музыки действует отдельно от условий программы.',loading='Загрузка примера…',ready='Готово к прослушиванию',error='Не удалось загрузить пример. Попробуй ещё раз.',save='Скачать этот пример',volume='Громкость',queue='Трек',presets=['Мягко','Баланс','Громко','Максимум']),
'de':dict(nav=['Programm','Anhören','Anleitung'],title=['Deine Musik.','Deine Dichte.'],lead='Analoger Charakter. Mit dem Original vergleichen und deine MP3 speichern.',shared='Gemeinsames Setup mit YouTube Downloader',heading='Den Unterschied hören',intro='Drei Musikausschnitte. Titel wählen, am Plattenspieler Play drücken und den PeakMP3-Regler drehen.',note='Dichtestufen 0–10 wurden mit PeakMP3 0.16.0 vorbereitet. A ist der ursprüngliche Ausschnitt, B die gewählte Bearbeitung. Eigene Dateien werden nicht im Browser verarbeitet.',hint='Regler, Presets, A/B und Transport ausprobieren. Auf der Wellenform springen, rechts die Lautstärke einstellen.',credit='Musik und Lizenzen',changes='24-Sekunden-Ausschnitte: Schnitt, PeakMP3-Bearbeitung und MP3-Kodierung. Die Musiklizenz gilt unabhängig von den Programmbedingungen.',loading='Beispiel wird geladen…',ready='Bereit zum Anhören',error='Beispiel konnte nicht geladen werden. Erneut versuchen.',save='Dieses Beispiel laden',volume='Lautstärke',queue='Titel',presets=['Sanft','Balance','Laut','Maximum']),
'en':dict(nav=['Application','Listen','Guide'],title=['Your music.','Your density.'],lead='Analog character. Compare with your original and save your MP3.',shared='Shared installer with YouTube Downloader',heading='Hear the difference',intro='Three short music examples. Choose a track, press Play on the turntable and turn the PeakMP3 knob.',note='Density levels 0–10 were prepared with PeakMP3 0.16.0. A is the original excerpt, B the selected processing. This demo does not process your files in the browser.',hint='Try the knob, presets, A/B and transport. Seek on the waveform and adjust volume with the fader on the right.',credit='Music and licenses',changes='24-second excerpts: trimming, PeakMP3 processing and MP3 encoding. Music licensing is separate from application terms.',loading='Loading example…',ready='Ready to listen',error='Could not load the example. Try again.',save='Download this example',volume='Volume',queue='Track',presets=['Soft','Balance','Loud','Maximum'])}
def nav(kind,l):
 d=UI[l];langs=''.join('<a class="lang" href="'+('Guide-' if kind=='guide' else 'index-')+x+'.html" lang="'+x+'"'+(' aria-current="true"' if x==l else '')+'>'+x.upper()+'</a>' for x in UI)
 links='<a href="https://popovantondev.github.io/popovantondev/'+('index.html' if l=='en' else 'index-'+l+'.html')+'">'+dict(ru='Все программы',de='Alle Programme',en='All applications')[l]+'</a>'+''.join('<a href="'+u+'">'+e(t)+'</a>' for u,t in zip(['index-'+l+'.html','index-'+l+'.html#demo','Guide-'+l+'.html'],d['nav']))
 return '<a class="skip" href="#content">'+e(c.D[l]['skip'])+'</a><header class="site-nav"><a class="brand" href="index-'+l+'.html">'+c.wave()+'<span>Peak<span class="word-orange">MP3</span></span></a><nav class="nav-links" id="site-menu">'+links+'</nav><nav class="languages" aria-label="Language">'+langs+'</nav><button class="menu-toggle" aria-expanded="false" aria-controls="site-menu" aria-label="'+e(c.D[l]['menu'])+'">'+c.icon('menu')+'</button></header>'
def footer(l):
 links=[('https://github.com/popovantondev/PeakMP3','GitHub'),('Guide-'+l+'.html',c.D[l]['nav'][2]),('https://popovantondev.github.io/YouTubeDownloader/index-'+l+'.html','YouTube Downloader'),('https://github.com/popovantondev/PeakMP3/issues/new',c.D[l]['support'])]
 return '<footer class="workflow-wrap"><div class="workflow"><div class="footer-links">'+''.join('<a href="'+u+'">'+e(t)+'</a>' for u,t in links)+'</div></div></footer>'
def demo(l):
 d=UI[l];tracks=json.loads((R/'music/tracks.json').read_text(encoding='utf-8'));buttons='';credits=''
 for n,t in enumerate(tracks):
  buttons+='<button class="track-choice" data-track="'+t['id']+'" aria-pressed="'+str(n==0).lower()+'"><span class="track-disc" aria-hidden="true"></span><span><strong>'+e(t['title'])+'</strong><small>'+e(t['genre'])+' · 24 s</small></span></button>'
  credits+='<li><a href="'+t['source']+'">'+e(t['title'])+'</a> — Kevin MacLeod (incompetech.com), <a href="https://creativecommons.org/licenses/by/4.0/">CC BY 4.0</a>.</li>'
 controls='<label class="demo-readout"><output class="density-number" id="density-number" for="density-range">7</output><span>'+e(c.D[l]['density'])+'</span></label><input id="density-range" class="density-range" type="range" min="0" max="10" value="7" aria-label="'+e(c.D[l]['density'])+'"><div class="demo-toolbar">'
 for key,label in [('a','A · '+c.D[l]['original']),('b','B · '+c.D[l]['processed'])]:controls+='<button class="hardware-button" data-compare="'+key+'" aria-pressed="'+str(key=='b').lower()+'">'+e(label)+'</button>'
 controls+='<button class="hardware-button" id="demo-play" aria-pressed="false">▶ '+e(c.D[l]['play'])+'</button><button class="hardware-button" id="demo-stop">■ '+e(c.D[l]['stop'])+'</button></div><label class="volume-row">'+e(d['volume'])+' <input id="demo-volume" type="range" min="0" max="100" value="60" aria-label="'+e(d['volume'])+'"></label><p class="demo-status" id="demo-state" role="status">'+e(d['ready'])+'</p><a class="export-example" id="demo-export" download>'+e(d['save'])+'</a>'
 return '<section class="interactive-section" id="demo"><div class="demo-copy"><span class="mini-chip">PeakMP3 · Audio demo</span><h2>'+e(d['heading'])+'</h2><p>'+e(d['intro'])+'</p><div class="track-list">'+buttons+'</div><p class="demo-small">'+e(d['hint'])+'</p>'+'<details class="extra-controls" open><summary>'+({'ru':'Дополнительное управление','de':'Weitere Bedienelemente','en':'Additional controls'}[l])+'</summary>'+controls+'</details><p class="demo-small">'+e(d['note'])+'</p><details class="music-credits"><summary>'+e(d['credit'])+'</summary><ul>'+credits+'</ul><p>'+e(d['changes'])+'</p></details></div><div class="demo-device"><canvas id="peak-demo" width="778" height="1293" tabindex="0" role="img" aria-label="'+e(d['hint'])+'"></canvas><p class="image-note">'+e(d['hint'])+'</p></div><audio id="demo-audio" preload="none"></audio></section>'
GUIDE={
'ru':dict(title='PeakMP3: от файла до готового MP3',lead='Локальные аудиофайлы работают без браузерного расширения. Установщик остаётся общим с YouTube Downloader.',audio='Открытие и обработка аудио',steps=['Запусти PeakMP3 и перетащи в область песни один или несколько MP3, AAC, WAV или FLAC. Несколько файлов образуют очередь.','Выбери плотность: 0 — оригинал, 1–9 — смесь с обработанным вариантом, 10 — «Максимум». Двойной щелчок по крутилке открывает ручной ввод целого числа; отрицательные значения уменьшают уровень оригинала, значения выше 10 добавляют усиление и ограничение пиков.','Нажми воспроизведение, сравни A/B. Перемотка доступна по волне и пластинке; фейдер справа меняет громкость прослушивания.','Нажми «Создать MP3 320» и выбери папку сохранения. По умолчанию диалог открывает рабочий стол. Исходный файл сохраняется.'],cal='Калибровка VU',calText='Нажми на винт под стрелкой. Выбери уровень dBFS, соответствующий 0 VU. Это настройка индикатора: она не меняет обработку, громкость файла или звук при сохранении.',integration='Подключение к YouTube Downloader',integrationText='Этот шаг нужен только для передачи AAC из браузера. Общий установщик содержит загрузчик и PeakMP3. В мастере подключения открой страницу расширений браузера, включи режим разработчика и загрузи распакованную папку extension, указанную мастером. Для локальных аудиофайлов этот шаг можно пропустить.',integrationHelp='После обновления перезагрузи расширение и вкладку YouTube. Если AAC не передаётся, открой зелёную стрелку и проверь связь с PeakMP3.',help='Если аудиофайл не открывается, проверь, что комплект полностью распакован и ffmpeg.exe находится рядом с PeakMP3.exe. Попробуй исходный файл в другом проигрывателе. Если не получается сохранить результат, проверь свободное место и доступ к выбранной папке. В сообщении об ошибке укажи версию PeakMP3, Windows, формат файла и точный текст ошибки.'),
'de':dict(title='PeakMP3: von der Datei zur fertigen MP3',lead='Lokale Audiodateien benötigen keine Browser-Erweiterung. Das Setup bleibt gemeinsam mit YouTube Downloader.',audio='Audio öffnen und bearbeiten',steps=['PeakMP3 starten und eine oder mehrere MP3-, AAC-, WAV- oder FLAC-Dateien auf den Titelbereich ziehen. Mehrere Dateien bilden eine Warteschlange.','Dichte wählen: 0 ist das Original, 1–9 mischen die bearbeitete Fassung hinzu, 10 ist Maximum. Ein Doppelklick auf den Regler öffnet die Ganzzahleingabe; negative Werte senken den Originalpegel, Werte über 10 ergänzen Verstärkung und Spitzenbegrenzung.','Wiedergabe starten und A/B vergleichen. Auf Wellenform oder Schallplatte springen; der rechte Fader ändert die Abhörlautstärke.','MP3 320 erstellen und den Zielordner wählen. Der Speicherdialog beginnt auf dem Desktop. Die Quelldatei bleibt erhalten.'],cal='VU-Kalibrierung',calText='Die Schraube unter dem Zeiger anklicken und den dBFS-Bezug für 0 VU wählen. Das ändert nur die Anzeige, nicht die Audiobearbeitung oder die gespeicherte Datei.',integration='Verbindung mit YouTube Downloader',integrationText='Nur für die AAC-Übergabe aus dem Browser erforderlich. Das gemeinsame Setup enthält Downloader und PeakMP3. Im Verbindungsassistenten die Erweiterungsverwaltung öffnen, den Entwicklermodus aktivieren und den angezeigten Ordner extension als entpackte Erweiterung laden. Für lokale Audiodateien ist das optional.',integrationHelp='Nach Updates Erweiterung und YouTube-Tab neu laden. Wenn AAC nicht übergeben wird, am grünen Pfeil die Verbindung mit PeakMP3 prüfen.',help='Wenn Audio nicht geöffnet wird, das vollständige Paket entpacken und ffmpeg.exe neben PeakMP3.exe prüfen. Die Quelle in einem anderen Player testen. Bei Speicherfehlern freien Platz und Schreibrechte im Zielordner prüfen. Im Fehlerbericht PeakMP3-Version, Windows, Dateiformat und die genaue Fehlermeldung nennen.'),
'en':dict(title='PeakMP3: from source audio to finished MP3',lead='Local audio files work without a browser extension. The installer remains shared with YouTube Downloader.',audio='Open and process audio',steps=['Open PeakMP3 and drop one or more MP3, AAC, WAV or FLAC files onto the track area. Multiple files form a queue.','Choose density: 0 is the original, 1–9 blend in the processed version, and 10 is Maximum. Double-click the knob to enter an integer; negative values attenuate the original, while values above 10 add gain and peak limiting.','Start playback and compare A/B. Seek on the waveform or record; the right fader controls listening volume.','Choose Create MP3 320 and select the destination folder. The save dialog starts on Desktop. Your source file is preserved.'],cal='VU calibration',calText='Click the screw below the needle and choose the dBFS reference for 0 VU. This adjusts the display only; it does not change audio processing or the saved file.',integration='Connect YouTube Downloader',integrationText='Only needed to send AAC from the browser. The shared installer includes Downloader and PeakMP3. In the connection wizard, open the browser extension manager, enable Developer mode and load the indicated extension folder as an unpacked extension. This is optional for local audio files.',integrationHelp='After updates, reload the extension and the YouTube tab. If AAC is not handed over, open the green arrow and check the PeakMP3 connection.',help='If audio will not open, extract the complete package and check that ffmpeg.exe is beside PeakMP3.exe. Try the source in another player. For save errors, check free space and write access to the destination. Include the PeakMP3 version, Windows version, file format and exact error text in a bug report.')}

def guide(l):
 g=GUIDE[l];d=c.D[l]
 sections=[('install',d['setupTitle'],'<ol>'+''.join('<li>'+e(x)+'</li>' for x in d['setupSteps'][:2])+'</ol>'+c.download(l,True)+'<div class="download-links"><a href="'+c.RELEASE+c.ZIP+'">'+e(d['fullZip'])+'</a><a href="'+c.RELEASE+'SHA256SUMS.txt">'+e(d['checksums'])+'</a></div>'),('audio',g['audio'],'<ol>'+''.join('<li>'+e(x)+'</li>' for x in g['steps'])+'</ol>'),('calibration',g['cal'],'<p>'+e(g['calText'])+'</p>'),('integration',g['integration'],'<p>'+e(g['integrationText'])+'</p><p><code>%LOCALAPPDATA%\\YTWin7_360_MP3\\extension</code></p><p>'+e(g['integrationHelp'])+'</p><p class="notice">'+e(d['limitation'])+'</p>'),('windows',d['osTitle'],'<p>'+e(d['osText'])+'</p><p>'+e(d['verified'])+'</p>'),('uninstall',d['removeTitle'],'<p>'+e(d['removeText'])+'</p>'),('help',d['helpTitle'],'<p>'+e(g['help'])+'</p>'),('rights',d['rights'],'<p><a href="https://github.com/popovantondev/PeakMP3/blob/main/RIGHTS.md">RIGHTS.md</a> · <a href="https://github.com/popovantondev/YouTubeDownloader/blob/main/THIRD_PARTY_NOTICES.md">FFmpeg / LAME</a> · <a href="music/CREDITS.md">CC BY 4.0</a></p>')]
 toc=''.join('<a href="#'+key+'">'+e(title)+'</a>' for key,title,body in sections)
 content=''.join('<section id="'+key+'"><h2>'+e(title)+'</h2>'+body+'</section>' for key,title,body in sections)
 return '<main id="content"><header class="guide-title"><p class="section-kicker">'+e(d['guidePreview'])+'</p><h1>'+e(g['title'])+'</h1><p>'+e(g['lead'])+'</p></header><div class="page-body guide-layout"><nav class="guide-toc" aria-label="'+e(d['guideToc'])+'">'+toc+'</nav><div class="guide-content">'+content+'</div></div></main>'+footer(l)

def main():
 c.nav=nav;c.footer=footer
 for l,d in UI.items():
  optional={'ru':'Для работы с локальными файлами расширение не требуется. После установки запусти PeakMP3 с рабочего стола, перетащи аудиофайлы, выбери плотность и сравни A/B.','de':'Für lokale Dateien ist keine Erweiterung nötig. PeakMP3 vom Desktop starten, Audiodateien hineinziehen, Dichte wählen und A/B vergleichen.','en':'Local audio files do not require the extension. Open PeakMP3 from Desktop, drop audio files, choose density and compare A/B.'}[l]
  c.D[l]['setupSteps']=[c.D[l]['setupSteps'][0],c.D[l]['setupSteps'][1],optional,c.D[l]['peakFeatures'][2][1]]
  c.D[l]['guidePreview']='PeakMP3 0.16.0 · '+d['shared']
  hero='<section class="hero product-hero"><div class="hero-copy"><p class="eyebrow">PeakMP3 · 0.16.0 Preview</p><h1 class="hero-title">'+''.join('<span>'+e(x)+'</span>' for x in d['title'])+'</h1><p class="lead">'+e(d['lead'])+'</p>'+c.actions(l)+'<p class="version-label">'+e(d['shared'])+'</p>'+c.badges(l)+'</div>'+c.shot(l)+'</section>'
  body='<main id="content">'+hero+'<div class="wood-divider"></div><div class="page-body">'+c.feature_row(c.D[l]['peakFeatures'])+demo(l)+'</div></main>'+footer(l)
  for kind,content in [('home',body),('guide',guide(l))]:
   html='<!doctype html><html lang="'+l+'"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="application-version" content="0.16.0"><title>PeakMP3</title><link rel="icon" href="assets/site/peakmp3.svg"><link rel="stylesheet" href="website/site.css"><link rel="stylesheet" href="website/peak.css"><script defer src="website/site.js"></script>'+('<script defer src="website/demo.js"></script>' if kind=='home' else '')+'</head><body class="peak-site" data-lang="'+l+'"><div class="site-shell"><div class="shell-inner">'+nav(kind,l)+content+'</div></div>'
   if kind=='home':html+='<script type="application/json" id="demo-strings">'+json.dumps(dict(c.D[l],**d),ensure_ascii=False).replace('</',r'<\/')+'</script>'
   html+='</body></html>'
   html=html.replace('https://github.com/popovantondev/YouTubeDownloader/blob/main/RIGHTS.md','https://github.com/popovantondev/PeakMP3/blob/main/RIGHTS.md')
   (R/(('index-' if kind=='home' else 'Guide-')+l+'.html')).write_text(html,encoding='utf-8')
 (R/'index.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><title>PeakMP3</title><script>var l;try{l=localStorage.getItem("studio.site.language")}catch(e){}l=l||navigator.language.slice(0,2);location.replace("index-"+(["ru","de","en"].includes(l)?l:"en")+".html");</script></head><body><a href="index-ru.html">Русский</a> · <a href="index-de.html">Deutsch</a> · <a href="index-en.html">English</a></body></html>',encoding='utf-8')
 print('Built standalone PeakMP3 pages RU/DE/EN')
if __name__=='__main__':
 main()
 import polish_guides
 polish_guides.main()
